use maho_rpc::rpc_client::{RpcSocketClient,ClientFrame};
use tokio::io::{AsyncReadExt,AsyncWriteExt};
#[tokio::test]async fn real_socket_correlates_response_before_following_event(){let(client,mut host)=tokio::net::UnixStream::pair().unwrap();let mut client=RpcSocketClient::from_stream(client);client.frames.session_id=Some("lease".into());let command=client.send(serde_json::json!({"type":"get_messages"}),true,true).await.unwrap();let mut bytes=vec![0;command.to_string().len()+1];host.read_exact(&mut bytes).await.unwrap();let request:serde_json::Value=serde_json::from_slice(&bytes).unwrap();assert_eq!(request["sessionId"],"lease");host.write_all(b"{\"type\":\"response\",\"id\":\"req_1\",\"success\":true}\n{\"type\":\"agent_start\",\"sessionId\":\"lease\"}\n").await.unwrap();assert!(matches!(client.receive().await.unwrap(),Some(ClientFrame::Response(_))));assert!(matches!(client.receive().await.unwrap(),Some(ClientFrame::Event(_))));host.shutdown().await.unwrap();assert!(client.receive().await.unwrap().is_none());assert!(client.frames.reject_pending().is_empty());}
